          sol: R`[[python3 hello.py]] هيطبع [[Hello]]، و [[node hello.js]] هيطبع [[Hello]]. على ويندوز اكتب [[python hello.py]] أو [[py hello.py]]. ولو قالك [[command not found]] أو [[is not recognized]] يبقى اللغة مش متسطبة: سطّبها بمدير الحزم (درس «مدير الحزم» فوق، أو تاب Python وتاب Node و npm).

ومن غير القوس الأخير، Python هيطبع الرسالة اللي تحت: في الملف ده، السطر رقم 1، فيه قوس [[(]] اتفتح ومتقفلش، والعلامة [[^]] بتشاور على مكانه. شوف الرسالة بتقولك المكان والمشكلة بالظبط. (ونسخ Python القديمة شكل رسالتها مختلف شوية.)`,
          solCode: R`  File "/home/ali/lab/hello.py", line 1
    print("Hello"
         ^
SyntaxError: '(' was never closed`
